    for cc in bars:
        r_,c0,c1=rail(cc)
    hosts={}
    for mk in marks:
        for cc in bars:
            r_,c0,c1=rail(cc)
            if c0<=mk[1]<=c1: hosts[mk]=cc; break
    S=set()
    for mk in marks:
        cc=hosts[mk]; r_,c0,c1=rail(cc)
        o=mk[1]-c0
