import numpy as np
from collections import Counter
def components(I,bg=None):
    H,W=I.shape; seen=np.zeros_like(I,bool); comps=[]
    for r in range(H):
        for c in range(W):
            if I[r,c]!=bg and not seen[r,c]:
                stack=[(r,c)]; seen[r,c]=True; cells=[]
                while stack:
                    rr,cc=stack.pop(); cells.append((rr,cc))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=rr+dr,cc+dc
                        if 0<=nr<H and 0<=nc<W and I[nr,nc]!=bg and not seen[nr,nc]:
                            seen[nr,nc]=True; stack.append((nr,nc))
                comps.append(cells)
    return comps

